import type {AIProvider, MessageChunk} from '../types/ai.js';

// A provider whose every turn rejects with `reason`, so a test can pin what the orchestrator does with that rejection.
export const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});
