import {createChatOrchestrator} from './chatOrchestrator.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {rejectingWith} from './rejectingProviderTestSupport.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const session: ChatSession = {
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
};

describe('ChatOrchestrator onError on an undefined rejection', () => {
  it('calls onError with an Error and still rejects to the caller with undefined', async () => {
    const seen: Error[] = [];
    const hooks = {
      onError: async (_session: ChatSession, error: Error) => {
        seen.push(error);
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(undefined), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(session)).rejects.toBeUndefined();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toBeInstanceOf(Error);
  });
});
